--
-- Struktur untuk view `v_jurnal_harian`
--
DROP VIEW IF EXISTS `v_jurnal_harian`;

CREATE VIEW `v_jurnal_harian` AS
SELECT
  `j`.`tanggal` AS `tanggal`,
  `jk`.`hari` AS `hari`,
  `jp`.`jam_ke` AS `jam_ke`,
  `jp`.`jam_mulai` AS `jam_mulai`,
  `jp`.`jam_selesai` AS `jam_selesai`,
  `mp`.`kode_mapel` AS `kode_mapel`,
  `mp`.`nama_mapel` AS `nama_mapel`,
  `g`.`nama` AS `guru_mengajar`,
  `gj`.`nama` AS `guru_terjadwal`,
  `j`.`status_guru` AS `keterangan_kehadiran`,
  `j`.`materi` AS `materi`,
  `j`.`catatan_guru` AS `catatan_guru`,
  `j`.`catatan_siswa` AS `catatan_siswa`,
  `s`.`nama_siswa` AS `diisi_oleh`
FROM ((((((`jurnal_kbm` `j`
  JOIN `jadwal_kbm` `jk` ON (`jk`.`id_jadwal` = `j`.`id_jadwal`))
  JOIN `jam_pelajaran` `jp` ON (`jp`.`id_jam` = `jk`.`id_jam`))
  JOIN `mata_pelajaran` `mp` ON (`mp`.`id_mapel` = `jk`.`id_mapel`))
  JOIN `guru` `g` ON (`g`.`id` = `j`.`id_guru`))
  JOIN `guru` `gj` ON (`gj`.`id` = `jk`.`id_guru`))
  LEFT JOIN `siswa` `s` ON (`s`.`id_siswa` = `j`.`id_siswa_pengisi`))
ORDER BY `j`.`tanggal` ASC, `jp`.`jam_ke` ASC;

-- --------------------------------------------------------

--
-- Struktur untuk view `v_template_jadwal_harian`
--
DROP VIEW IF EXISTS `v_template_jadwal_harian`;

CREATE VIEW `v_template_jadwal_harian` AS
SELECT
  `jk`.`id_jadwal` AS `id_jadwal`,
  `jk`.`id_kelas` AS `id_kelas`,
  `jk`.`hari` AS `hari`,
  `jp`.`jam_ke` AS `jam_ke`,
  `jp`.`jam_mulai` AS `jam_mulai`,
  `jp`.`jam_selesai` AS `jam_selesai`,
  `mp`.`kode_mapel` AS `kode_mapel`,
  `mp`.`nama_mapel` AS `nama_mapel`,
  `jk`.`id_guru` AS `id_guru`,
  `g`.`nama` AS `nama_guru`
FROM (((`jadwal_kbm` `jk`
  JOIN `jam_pelajaran` `jp` ON (`jp`.`id_jam` = `jk`.`id_jam`))
  JOIN `mata_pelajaran` `mp` ON (`mp`.`id_mapel` = `jk`.`id_mapel`))
  JOIN `guru` `g` ON (`g`.`id` = `jk`.`id_guru`))
WHERE `jp`.`jenis` = 'KBM'
ORDER BY `jk`.`hari` ASC, `jp`.`jam_ke` ASC;

-- --------------------------------------------------------

--
-- Struktur untuk view `v_users_with_roles`
--
DROP VIEW IF EXISTS `v_users_with_roles`;

CREATE VIEW `v_users_with_roles` AS
SELECT
  `u`.`id_user` AS `id_user`,
  `u`.`username` AS `username`,
  `u`.`email` AS `email`,
  `u`.`is_aktif` AS `is_aktif`,
  `u`.`id_guru` AS `id_guru`,
  `u`.`id_siswa` AS `id_siswa`,
  GROUP_CONCAT(`r`.`kode_role` ORDER BY `r`.`kode_role` ASC SEPARATOR ', ') AS `roles`,
  COALESCE(`g`.`nama`, `s`.`nama_siswa`) AS `nama_lengkap`
FROM ((((`users` `u`
  LEFT JOIN `user_roles` `ur` ON (`ur`.`id_user` = `u`.`id_user`))
  LEFT JOIN `roles` `r` ON (`r`.`id_role` = `ur`.`id_role`))
  LEFT JOIN `guru` `g` ON (`g`.`id` = `u`.`id_guru`))
  LEFT JOIN `siswa` `s` ON (`s`.`id_siswa` = `u`.`id_siswa`))
GROUP BY
  `u`.`id_user`,
  `u`.`username`,
  `u`.`email`,
  `u`.`is_aktif`,
  `u`.`id_guru`,
  `u`.`id_siswa`,
  `g`.`nama`,
  `s`.`nama_siswa`;

